INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (103, 191, 'BOPS Sheets (polystyrene sheets) for food container', '../upload/image/20181226/20181226121523_48831.jpg', '<p></p><p><span style="color:#009900;font-family:Verdana;">BOPS Sheets (polystyrene sheets) for food container</span></p> <p><span style="color:#009900;font-family:Verdana;">BOPS sheets(polystyrene sheets in roll sizes) have clear ( transparent) and color (such as: red, green, blue, black,yellow...),BOPS Film</span><br/> <span style="color:#009900;font-family:Verdana;"> Biaxially Oriented Polystyrene for plastic Food Containers, PET Container,PP Container </span><br/> <span style="color:#009900;font-family:Verdana;"> thickness: 120-500Microns</span><br/> <span style="color:#009900;font-family:Verdana;"> Width:340-1500MM</span><br/> <span style="color:#009900;font-family:Verdana;"> Length: 1000,1500M . </span><br/> <span style="color:#009900;font-family:Verdana;"> Quantity:750,000tons. </span><br/> <span style="color:#009900;font-family:Verdana;"> Application: to make (food storage)crispers.</span></p> <p><br/></p>', '2026-09-06 20:58:45');